        if (target <= 0) {
            return;
        }

        for (int value = start; value <= 9; ++value) {
            if (value > target) {
                break;
            }

            current.push_back(value);
            search(value + 1, left - 1, target - value,
                   current, answer);
            current.pop_back();
        }
    }

