## Solution
```java[]
class Solution {
    public List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> ans = new ArrayList<>();
        List<Integer> temp = new ArrayList<>();
        recSolution(ans, temp, 1, k, n, 0); // start from 1
        return ans;
    }

    public void recSolution(List<List<Integer>> ans, List<Integer> temp,
                            int currIndex, int k, int n, int sum) {
        // base case: if we picked k numbers
        if (temp.size() == k) {
            if (sum == n) {
                ans.add(new ArrayList<>(temp)); // record valid subset
            }
            return;
        }

        // try numbers from currIndex to 9
        for (int i = currIndex; i <= 9; i++) {
            if (sum + i > n) break; // pruning
            temp.add(i);
            recSolution(ans, temp, i+1, k, n, sum+i); // move forward
            temp.remove(temp.size()-1); // backtrack
        }
    }
}

```

